	/**
	 * Undo the last 'count' transactions on the domain object and wait for all events to be
	 * flushed.
	 *
	 * @param dobj The domain object upon which to perform the undo.
	 * @param count number of transactions to undo
	 */
	public static void undo(DomainObject dobj, int count) {
		for (int i = 0; i < count; ++i) {
			undo(dobj);
		}
	}

	/**
	 * Redo the last 'count' undone transactions on the domain object and wait for all events to be
	 * flushed.
	 *
	 * @param dobj The domain object upon which to perform the redo.
	 * @param count number of transactions to redo
	 */
	public static void redo(DomainObject dobj, int count) {
		for (int i = 0; i < count; ++i) {
			redo(dobj);
		}
	}

	public static T getPlugin<T>/* where T : Plugin */(PluginTool tool, Class<T> c) {
		List<Plugin> list = tool.getManagedPlugins();
		foreach (Plugin p in list) {
			if (p.GetType() == c) {
				return c.cast(p);
			}
		}
		return null;
	}

	public AddressSet toAddressSet(Program p, string from, string to) {
		AddressFactory af = p.getAddressFactory();
		Address a1 = af.getAddress(from);
		Address a2 = af.getAddress(to);
		return af.getAddressSet(a1, a2);
	}

	public AddressSet toAddressSet(List<Address> addrs) {
		AddressSet set = new AddressSet();
		foreach (Address addr in addrs) {
			set.add(addr);
		}
		return set;
	}

	public AddressSet toAddressSet(Address start, Address end) {
		AddressSet set = new AddressSet();
		set.addRange(start, end);
		return set;
	}

	public AddressSet toAddressSet(params AddressRange[] ranges) {
		AddressSet set = new AddressSet();
		foreach (AddressRange range in ranges) {
			set.add(range);
		}
		return set;
	}

	public void goTo(PluginTool tool, Program p, Address addr) {

		GoToService goTo = tool.getService(typeof(GoToService));
		if (goTo != null) {
			goTo.goTo(addr);
			waitForSwing();
			return;
		}

		tool.firePluginEvent(
			new ProgramLocationPluginEvent("Test", new ProgramLocation(p, addr), p));
		waitForSwing();
	}

	public void goTo(PluginTool tool, Program p, string addrString) {
		AddressFactory factory = p.getAddressFactory();
		Address addr = factory.getAddress(addrString);
		tool.firePluginEvent(
			new ProgramLocationPluginEvent("Test", new ProgramLocation(p, addr), p));
		waitForSwing();
	}

	public void makeSelection(PluginTool tool, Program p, List<Address> addrs) {
